// components/professor/QuizCreation.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const QuizCreation = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(1);
  const [quiz, setQuiz] = useState({
    title: '',
    description: '',
    timeLimit: 30,
    isPublic: true,
    questions: []
  });

  const [currentQuestion, setCurrentQuestion] = useState({
    text: '',
    type: 'multiple_choice',
    points: 1,
    options: [
      { text: '', isCorrect: false },
      { text: '', isCorrect: false },
      { text: '', isCorrect: false },
      { text: '', isCorrect: false }
    ]
  });

  const handleQuizChange = (e) => {
    const { name, value, type, checked } = e.target;
    setQuiz({
      ...quiz,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  const handleQuestionChange = (e) => {
    const { name, value } = e.target;
    setCurrentQuestion({
      ...currentQuestion,
      [name]: value
    });
  };

  const handleOptionChange = (index, e) => {
    const { name, value, type, checked } = e.target;
    const updatedOptions = [...currentQuestion.options];

    if (type === 'checkbox' || type === 'radio') {
      if (currentQuestion.type === 'multiple_choice' && checked) {
        updatedOptions.forEach(option => option.isCorrect = false);
      }
      updatedOptions[index] = {
        ...updatedOptions[index],
        isCorrect: checked
      };
    } else {
      updatedOptions[index] = {
        ...updatedOptions[index],
        [name]: value
      };
    }

    setCurrentQuestion({
      ...currentQuestion,
      options: updatedOptions
    });
  };

  const addOption = () => {
    if (currentQuestion.options.length < 8) {
      setCurrentQuestion({
        ...currentQuestion,
        options: [...currentQuestion.options, { text: '', isCorrect: false }]
      });
    }
  };

  const removeOption = (index) => {
    if (currentQuestion.options.length > 2) {
      const updatedOptions = currentQuestion.options.filter((_, i) => i !== index);
      setCurrentQuestion({
        ...currentQuestion,
        options: updatedOptions
      });
    }
  };

  const addQuestion = () => {
    const valid = currentQuestion.text.trim() !== '';
    const hasCorrectAnswer = currentQuestion.options.some(option => option.isCorrect);

    if (!valid || !hasCorrectAnswer) {
      alert('Veuillez compléter la question et marquer au moins une réponse comme correcte.');
      return;
    }

    setQuiz({
      ...quiz,
      questions: [...quiz.questions, { ...currentQuestion, id: Date.now() }]
    });

    setCurrentQuestion({
      text: '',
      type: 'multiple_choice',
      points: 1,
      options: [
        { text: '', isCorrect: false },
        { text: '', isCorrect: false },
        { text: '', isCorrect: false },
        { text: '', isCorrect: false }
      ]
    });
  };

  const editQuestion = (index) => {
    setCurrentQuestion(quiz.questions[index]);
    const updatedQuestions = quiz.questions.filter((_, i) => i !== index);
    setQuiz({
      ...quiz,
      questions: updatedQuestions
    });
  };

  const removeQuestion = (index) => {
    const updatedQuestions = quiz.questions.filter((_, i) => i !== index);
    setQuiz({
      ...quiz,
      questions: updatedQuestions
    });
  };

  const nextStep = () => {
    if (currentStep === 1 && !quiz.title.trim()) {
      alert('Veuillez donner un titre à votre quiz.');
      return;
    }
    setCurrentStep(currentStep + 1);
  };

  const prevStep = () => {
    setCurrentStep(currentStep - 1);
  };

  const saveQuiz = () => {
    console.log('Quiz saved:', quiz);
    setTimeout(() => {
      alert('Quiz créé avec succès!');
      navigate('/professor/manage-quiz');
    }, 1000);
  };

  return (
    <div className="content-area">
      <h1>Créer un Nouveau Quiz</h1>

      <div className="stepper mb-4">
        <div className={`step ${currentStep >= 1 ? 'active' : ''}`}>
          <div className="step-number">1</div>
          <div className="step-label">Informations du Quiz</div>
        </div>
        <div className="step-connector"></div>
        <div className={`step ${currentStep >= 2 ? 'active' : ''}`}>
          <div className="step-number">2</div>
          <div className="step-label">Ajouter des Questions</div>
        </div>
        <div className="step-connector"></div>
        <div className={`step ${currentStep >= 3 ? 'active' : ''}`}>
          <div className="step-number">3</div>
          <div className="step-label">Récapitulatif</div>
        </div>
      </div>

      {currentStep === 1 && (
        <div className="quiz-info">
          <div className="form-group">
            <label htmlFor="title">Titre du Quiz</label>
            <input
              type="text"
              id="title"
              name="title"
              value={quiz.title}
              onChange={handleQuizChange}
              placeholder="Entrez le titre du quiz"
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="description">Description</label>
            <textarea
              id="description"
              name="description"
              value={quiz.description}
              onChange={handleQuizChange}
              placeholder="Entrez une description pour votre quiz"
              rows="4"
            ></textarea>
          </div>

          <div className="form-group">
            <label htmlFor="timeLimit">Temps limite (en minutes)</label>
            <input
              type="number"
              id="timeLimit"
              name="timeLimit"
              value={quiz.timeLimit}
              onChange={handleQuizChange}
              min="1"
              max="180"
            />
          </div>

          <div className="form-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                name="isPublic"
                checked={quiz.isPublic}
                onChange={handleQuizChange}
              />
              Rendre ce quiz public pour tous les étudiants
            </label>
          </div>

          <div className="form-actions">
            <button className="btn btn-primary" onClick={nextStep}>Continuer</button>
          </div>
        </div>
      )}

      {currentStep === 2 && (
        <div className="quiz-questions">
          <h2>Ajouter une Question</h2>

          <div className="form-group">
            <label htmlFor="questionText">Question</label>
            <textarea
              id="questionText"
              name="text"
              value={currentQuestion.text}
              onChange={handleQuestionChange}
              placeholder="Entrez votre question"
              rows="2"
              required
            ></textarea>
          </div>

          <div className="form-group">
            <label htmlFor="questionType">Type de Question</label>
            <select
              id="questionType"
              name="type"
              value={currentQuestion.type}
              onChange={handleQuestionChange}
            >
              <option value="multiple_choice">Choix Multiple (une réponse)</option>
              <option value="checkbox">Cases à Cocher (plusieurs réponses)</option>
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="points">Points</label>
            <input
              type="number"
              id="points"
              name="points"
              value={currentQuestion.points}
              onChange={handleQuestionChange}
              min="1"
              max="10"
            />
          </div>

          <h3>Options</h3>
          {currentQuestion.options.map((option, index) => (
            <div className="option-row" key={index}>
              <input
                type="text"
                name="text"
                value={option.text}
                onChange={(e) => handleOptionChange(index, e)}
                placeholder={`Option ${index + 1}`}
                required
              />

              <label className="checkbox-label">
                <input
                  type={currentQuestion.type === 'multiple_choice' ? 'radio' : 'checkbox'}
                  name="isCorrect"
                  checked={option.isCorrect}
                  onChange={(e) => handleOptionChange(index, e)}
                />
                Correcte
              </label>

              <button
                type="button"
                className="btn btn-danger"
                onClick={() => removeOption(index)}
                disabled={currentQuestion.options.length <= 2}
              >
                Supprimer
              </button>
            </div>
          ))}

          <button
            type="button"
            className="btn btn-secondary"
            onClick={addOption}
            disabled={currentQuestion.options.length >= 8}
          >
            + Ajouter une option
          </button>

          <div className="form-actions">
            <button type="button" className="btn btn-success" onClick={addQuestion}>
              Ajouter la Question
            </button>
            <button type="button" className="btn btn-primary" onClick={nextStep}>
              Continuer
            </button>
            <button type="button" className="btn btn-secondary" onClick={prevStep}>
              Retour
            </button>
          </div>

          <h3>Questions Ajoutées</h3>
          <ul>
            {quiz.questions.map((q, index) => (
              <li key={q.id}>
                {q.text} ({q.points} pts)
                <button onClick={() => editQuestion(index)}>Modifier</button>
                <button onClick={() => removeQuestion(index)}>Supprimer</button>
              </li>
            ))}
          </ul>
        </div>
      )}

      {currentStep === 3 && (
        <div className="quiz-summary">
          <h2>Récapitulatif du Quiz</h2>
          <p><strong>Titre:</strong> {quiz.title}</p>
          <p><strong>Description:</strong> {quiz.description}</p>
          <p><strong>Temps Limite:</strong> {quiz.timeLimit} minutes</p>
          <p><strong>Public:</strong> {quiz.isPublic ? 'Oui' : 'Non'}</p>

          <h3>Questions</h3>
          <ul>
            {quiz.questions.map((q, index) => (
              <li key={q.id}>
                {q.text} ({q.points} pts)
              </li>
            ))}
          </ul>

          <div className="form-actions">
            <button type="button" className="btn btn-success" onClick={saveQuiz}>
              Enregistrer le Quiz
            </button>
            <button type="button" className="btn btn-secondary" onClick={prevStep}>
              Retour
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreation;
